-- ============================================================
-- 144 · Pilotul de studii: „Giuoco Piano" şi „Giuoco Piano cu 4…d6"
--
-- Cerut pe 2026-11-26 (modelul de studii, vezi migrarea 143): cel mult 3 studii
-- pe capitol (linia principală + cele mai frecvente 2 abateri), cel mult 13
-- variante pe studiu; o abatere cu ≥10% din partidele capitolului devine
-- capitol separat (aici 4…d6, 30%). Variantele: abaterile adversarului de ≥5%
-- (1000–1600, Chess.com), lungime variabilă — se opresc la avantaj clar
-- (≥ +1,0 de la mutarea 8) sau la mutarea 14. Linia principală a Giuoco Piano
-- urmează acum 11…O-O (89% din partide), nu 11…a5.
-- ============================================================

-- A: coada liniei principale (planul de joc de mijloc lipit la capăt).
update public.middlegame_plans p set
  moves_uci = 'c6e7 e1g1 e8g8 f1e1 c7c6 d2e4 b7b5 c4d3',
  move_explanations = $j${"0":"Cce7 — adversarul apără calul de pe d5 cu celălalt cal, de pe c6.","1":"Rocada ta. Regele e la adăpost, iar tura de pe f1 poate veni în centru.","2":"Rocada adversarului.","3":"Tfe1 — tura vine pe coloana e şi ţinteşte calul de pe e7.","4":"c6 — adversarul sprijină calul de pe d5 încă o dată.","5":"Ce4 — calul vine pe e4, de unde poate sări pe c5 sau g5.","6":"b5 — adversarul atacă nebunul de pe c4 cu pionul.","7":"Nd3 — nebunul se retrage pe d3 şi ţinteşte acum spre regele adversarului."}$j$::jsonb,
  final_text = $j$"Ai toate piesele în joc: calul de pe e4 şi nebunul de pe d3 ţintesc flancul regelui, iar tura ocupă coloana e. Pionul tău de pe d4 e singur, dar îţi dă spaţiu; caută atacul cu Cc5 sau Ceg5."$j$::jsonb#>>'{}',
  move_comments = null, move_hints = null, move_marks = null, final_arrows = null
  from public.opening_lines l join public.courses c on c.id = l.course_id
 where p.opening_line_id = l.id and c.slug = 'italian-game' and l.variation_code = 'A';

update public.opening_lines l set variante = $j$[{"nume":"Dacă adversarul joacă 4…h6","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 h7h6 b2b4 c5b6 b4b5 c6a5 c4f7 e8f7 f3e5","move_explanations":{"7":"h6 — adversarul împiedică Cg5 şi Ng5, dar pierde un timp: nu scoate nicio piesă.","8":"b4 — ataci nebunul de pe c5 cu pionul.","9":"Nb6 — nebunul se retrage pe b6.","10":"b5 — ataci şi calul de pe c6, care apără pionul de pe e5.","11":"Ca5 — calul fuge şi atacă nebunul de pe c4.","12":"Nxf7+ — nu-ţi retragi nebunul: îl dai pe f7, cu şah.","13":"Rxf7 — regele ia nebunul.","14":"Cxe5+ — iei pionul de pe e5 cu şah."},"final_text":"Ai dat nebunul pe doi pioni, dar regele adversarului a ieşit din adăpost, iar calul de pe a5 stă departe de joc. Urmează Dh5+ sau d4, cu atac puternic.","popularitate_pe_rating":{"chesscom":{"400":5.9,"700":8,"1000":9,"1300":7.7,"1600":4.6,"1900":2.6},"lichess":{"400":3.5,"1000":5.9,"1200":7,"1400":7.3,"1600":6.1,"1800":3.8,"2000":1.8,"2200":0.4}}},{"nume":"Dacă adversarul face rocada la mutarea 7","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d4 e5d4 c3d4 c5b4 c1d2 e8g8 d2b4 c6b4 e4e5 f8e8 e1g1","move_explanations":{"13":"Rocada adversarului: în loc să schimbe nebunii pe d2, îşi lasă nebunul pe b4.","14":"Nxb4 — iei nebunul de pe b4.","15":"Cxb4 — calul ia înapoi.","16":"e5 — ataci calul de pe f6 cu pionul.","17":"Te8 — adversarul nu retrage calul, ci atacă pionul de pe e5 cu tura.","18":"Rocada ta: îţi scoţi regele de pe coloana e, unde stă tura adversarului."},"final_text":"Calul de pe f6 e încă atacat de pionul de pe e5, iar adversarul trebuie să-l salveze. Ai mai mult spaţiu; urmează Cc3 şi a3, ca să alungi şi calul de pe b4.","popularitate_pe_rating":{"chesscom":{"400":5.3,"700":5.7,"1000":6.3,"1300":6.4,"1600":5.3,"1900":3.8},"lichess":{"400":4.5,"1000":4.2,"1200":4.9,"1400":5.6,"1600":5.7,"1800":5,"2000":3.5,"2200":1.2}}},{"nume":"Dacă adversarul face rocada la mutarea 8","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d4 e5d4 c3d4 c5b4 c1d2 b4d2 b1d2 e8g8 e4e5 f6e8 e1g1 d7d6 f1e1 d6e5 d4e5","move_explanations":{"15":"Rocada adversarului: în loc să lovească în centru cu d5, îşi pune regele la adăpost.","16":"e5 — ataci calul de pe f6 cu pionul. Câştigi spaţiu, iar calul trebuie să plece.","17":"Ce8 — calul se retrage înapoi, pe e8.","18":"Rocada ta. Regele e la adăpost, iar tura de pe f1 poate veni pe e1.","19":"d6 — adversarul atacă pionul de pe e5, ca să-şi elibereze jocul.","20":"Te1 — aperi pionul de pe e5 cu tura şi ocupi coloana e.","21":"dxe5 — adversarul schimbă pionii.","22":"dxe5 — iei înapoi. Pionul de pe e5 îi ia calului câmpurile d6 şi f6, iar tu ai mai mult spaţiu."},"final_text":"Ai un pion puternic pe e5, care îi ţine calul de pe e8 în spate. Planul: calul de pe d2 vine spre e4, apoi te uiţi spre flancul regelui.","popularitate_pe_rating":{"chesscom":{"400":50.1,"700":52.9,"1000":52.5,"1300":45.8,"1600":31.1,"1900":18.7},"lichess":{"400":41.4,"1000":44.9,"1200":48.4,"1400":48.5,"1600":43.9,"1800":32.4,"2000":16.2,"2200":4.4}}},{"nume":"Dacă adversarul joacă 9…Te8","moves_uci":"e2e4 e7e5 g1f3 b8c6 f1c4 f8c5 c2c3 g8f6 d2d4 e5d4 c3d4 c5b4 c1d2 b4d2 b1d2 e8g8 e4e5 f8e8 e1g1 f6g4 h2h3 g4h6 f1e1","move_explanations":{"15":"Rocada adversarului: în loc să lovească în centru cu d5, îşi pune regele la adăpost.","16":"e5 — ataci calul de pe f6 cu pionul. Câştigi spaţiu, iar calul trebuie să plece.","17":"Te8 — în loc să retragă calul, adversarul aduce tura pe coloana e, în faţa pionului tău.","18":"Rocada ta: înainte să iei calul, îţi scoţi regele de pe coloana e, unde stă tura adversarului.","19":"Cg4 — calul sare pe g4, de unde atacă pionul de pe e5.","20":"h3 — alungi calul cu pionul.","21":"Ch6 — calul se retrage pe margine, pe h6.","22":"Te1 — aperi pionul de pe e5 cu tura."},"final_text":"Calul de pe h6 stă prost, pe marginea tablei, iar pionul tău de pe e5 îţi dă spaţiu. Urmează Ce4 şi nebunul de pe c4 pe d3, cu ochii pe regele adversarului.","popularitate_pe_rating":{"c