do $$
declare na int; na2 int; sa int; sa2 int;
begin
  select jsonb_array_length(variante), jsonb_array_length(studii) into na, sa from public.opening_lines l
    join public.courses c on c.id = l.course_id where c.slug = 'italian-game' and l.variation_code = 'A';
  select jsonb_array_length(variante), jsonb_array_length(studii) into na2, sa2 from public.opening_lines l
    join public.courses c on c.id = l.course_id where c.slug = 'italian-game' and l.variation_code = 'A2';
  if na <> 29 or sa <> 3 or na2 <> 19 or sa2 <> 3 then
    raise exception 'Pilot: A % variante / % studii, A2 % / %; aşteptat 29/3 şi 19/3', na, sa, na2, sa2;
  end if;
end $$;
